import sys
sys.dont_write_bytecode=True
import additional_pfp_domain_remaining_audit as a
notes=a.read('_notes.json');probes=a.read('_cycle_probes.json');notes['controls'].extend(probes['controls'])
def ev(path,*ranges):return {'path':path,'sha256':a.row(path)['sha256'],'lines':[list(x) for x in ranges]}
def add(id,title,statement,evidence,controls):
 notes['findings'].append({'id':id,'title':title,'statement':statement,'evidence':list(dict.fromkeys(x['path'] for x in evidence)),'source_evidence':evidence,'control_ids':controls,'status':'confirmed_bounded_source_and_probe','limits':'Read-vetted Python3.14.2 modules under inert namespace packages; no native or provider execution, and no claim that an external production caller was exercised.'})
add('PFPDOMAIN-F005','Empty boundary-matrix transpose loses declared shape','BoundaryMatrix(0,2,()).transpose() returns0-by-0 rather than2-by-0. The constructor explicitly supports nonnegative dimensions with zero rows, so this is a supported empty-dimension case, not malformed data. Transpose involution and subsequent shape-sensitive chain operations can fail.',[ev('pfp/domain/homology/cochain.py',(24,45),(70,76))],['PFPDOMAIN-C005'])
add('PFPDOMAIN-F006','Replacing candidate or verifier preserves a stale verified receipt','Starting from a bound complete quartet, submit_candidate with a new candidate or bind_verifier with a new verifier returns Ok but retains the old receipt and is_verified flag. is_complete remains true although the receipt no longer binds the current object. These public mutators violate the aggregate consistency claim without requiring direct field mutation; rechecking validate_invariants would reveal the mismatch but the methods do not call it.',[ev('pfp/domain/aggregates/cycle_balance_aggregate.py',(104,149),(188,201))],['PFPDOMAIN-C006','PFPDOMAIN-C007'])
add('PFPDOMAIN-F007','Quartet constructor omits verifier-to-problem binding','The constructor synchronizes digests and validates candidate and receipt references but never compares verifier.problem_digest with the attached problem. A receipt can correctly bind the supplied candidate/problem/verifier hashes while the verifier contract names another problem, and is_complete is true. bind_verifier checks this relation, demonstrating inconsistent entry paths.',[ev('pfp/domain/aggregates/cycle_balance_aggregate.py',(53,102),(128,149),(193,201)),ev('pfp/domain/entities/cycle_balance.py',(250,252))],['PFPDOMAIN-C008'])
add('PFPDOMAIN-F008','Complete quartet accepts a mismatched receipt self-digest','ReceiptEntity accepts an existing Sha256Digest without recomputing it. Quartet checks only reference hashes, then copies the caller-provided VERIFIED status; a receipt with all-zero wrong self-digest and null terminal/witness fields yields is_complete true. This is a demonstrated receipt-integrity/assurance gap, not a claim that content hashes should prove mathematical correctness. Actual host/native verification must remain a separate trusted input.',[ev('pfp/domain/entities/cycle_balance.py',(273,350)),ev('pfp/domain/aggregates/cycle_balance_aggregate.py',(69,102),(151,201))],['PFPDOMAIN-C009'])
add('PFPDOMAIN-F009','Canonical digest and normal-form IDs accept a trailing newline','Sha256Digest validates with regex.match and a dollar anchor, which permits a final newline; a65-character value is accepted despite the exactly64-hex contract. NormalFormId similarly accepts nf.test.example followed by newline. General string IDs separately reject trailing whitespace. This establishes inconsistent canonical representation validation, not a forged matching SHA256.',[ev('pfp/domain/value_objects/identifiers.py',(15,17),(143,155),(181,193))],['PFPDOMAIN-C011'])
for id,title,statement,evidence in [
('PFPDOMAIN-CL01','Exact arithmetic is conditional on representation and supplied algorithm contracts','Fraction and Q arithmetic can make rational equality a decision rather than a tolerance, but the repository has different wire dialects and exactness does not verify the upstream model. Linear algebra ports validate input shape/type yet trust returned calculations; method names and runtime protocols are not proof witnesses.',[ev('pfp/domain/shared_kernel/exact.py',(43,122)),ev('pfp/domain/exact/linalg.py',(26,115)),ev('pfp/domain/ports/exact_ports.py',(23,89))]),
('PFPDOMAIN-CL02','Status-bearing records must remain distinct from host verification','Domain Result, EvaluationVerdict, GenesisCycleVerdict, SmithNormalFormResult, DualCertificate and VERIFIED receipts are primarily data containers. Several constructors enforce only syntax or partial consistency and default evidence-ceiling strings do not validate arithmetic, provenance or authority. Complete lifecycle success is unsound under the demonstrated stale-binding mutations until a caller adds the missing invariant checks.',[ev('pfp/domain/kernel/result.py',(81,174),(210,241)),ev('pfp/domain/homology/cochain.py',(142,162)),ev('pfp/domain/aggregates/cycle_balance_aggregate.py',(104,201))]),
('PFPDOMAIN-CL03','DDC tape summaries are endpoint bookkeeping, not replay certificates','DDCTape.is_fuel_conserved checks initial fuel minus total costs against only the final recorded fuel; per-step fuel and carrier transitions can be inconsistent while both fuel and monotone summary properties are true and final_status defaults PASS. The independent control exhibits that boundary. No primitive semantics, history alignment or proof of executed steps is implemented by these records.',[ev('pfp/domain/homology/ddc.py',(27,74))])]:
 notes['claims'].append({'id':id,'title':title,'statement':statement,'evidence':list(dict.fromkeys(x['path'] for x in evidence)),'source_evidence':evidence,'status':'bounded_scope_assessment'})
a.write('_notes.json',notes);a.report()
